import osimport numpy as npimport pandas as pdimport matplotlib.pyplot as pltfrom sklearn.feature_extraction.text import TfidfVectorizerfrom sklearn.decomposition import NMFfrom analisis import utilidades as uQUITAR = ["cdmx", "mexico", "ciudad", "city", "df", "not", "no", "nunca", "never"]RANGO = range(3, 13)MINIMO = 100TOL = 0.015# Nombres asignados a mano revisando palabras clave y comentarios de 3_temas.csv# Si cambian los datos, revisar de nuevo el CSV y actualizarNOMBRES = {    ("positivos", 0): "Barrios para caminar, comer y salir",    ("positivos", 1): "Murales de Diego Rivera",    ("positivos", 2): "«Vale la pena visitarlo»",    ("positivos", 3): "Museos y arte",    ("positivos", 4): "Arquitectura y Centro Histórico",    ("positivos", 5): "Planeación de viajes",    ("positivos", 6): "Experiencias familiares y entretenimiento",    ("positivos", 7): "Mercados y artesanías",    ("negativos", 0): "Experiencias y opiniones de viaje",    ("negativos", 1): "Mal servicio en parques y atracciones",    ("negativos", 2): "Comparaciones con otros países",    ("negativos", 3): "Zoológico de Chapultepec descuidado",    ("negativos", 4): "Reseñas mixtas de museos y murales",    ("negativos", 5): "Comida callejera",    ("negativos", 6): "Zonas sucias o inseguras",    ("negativos", 7): "Planeación de días y traslados",    ("negativos", 8): "Noticias (explosión en Iztapalapa)",}def npmi(B, H, top=10):    n = B.shape[0]    vals = []    for h in H:        s = B[:, np.argsort(-h)[:top]].toarray()        p = s.mean(axis=0)        pij = (s.T @ s) / n        for a in range(top):            for b in range(a + 1, top):                if pij[a, b] == 0:                    vals.append(-1)                elif pij[a, b] >= 1:                    vals.append(1)                else:                    vals.append(np.log(pij[a, b] / (p[a] * p[b])) / -np.log(pij[a, b]))    return np.mean(vals)def graf_k(coh, k, g, ruta):    fig, ax = plt.subplots(figsize=(7, 3.8))    m = max(coh.values())    ax.axhspan(m - TOL, m, color="#bfc3c9", alpha=0.4, label=f"A menos de {TOL} del máximo")    ax.plot(list(coh), list(coh.values()), marker="o", color="#2f6c8e")    ax.axvline(k, color="#440154", ls="--", label=f"k elegido = {k}")    ax.set_xlabel("Número de temas (k)")    ax.set_ylabel("Coherencia NPMI (más alto = mejor)")    ax.set_title(f"¿Cuántos temas? Textos {g}")    ax.legend(frameon=False, fontsize=8)    ax.spines[["top", "right"]].set_visible(False)    u.guardar(fig, ruta)def graf_proyectado(r, g, fuentes, n, paleta, ruta):    col, tra = u.colores(fuentes, paleta), u.tramas(fuentes)    fig, ax = plt.subplots(figsize=(10, 0.7 * len(r) + 1.5))    y = np.arange(len(r))    alto = 0.8 / len(fuentes)    for i, f in enumerate(fuentes):        if "pct_" + f in r:            ax.barh(y + (len(fuentes) / 2 - i - 0.5) * alto, r["pct_" + f].fillna(0), alto,                    color=col[f], hatch=tra[f], edgecolor="white", label=f"{u.nombre(f)} (n={n[f]:,})")    ax.set_yticks(y, r["nombre"], fontsize=9)    ax.set_xlabel("% de los textos de cada fuente")    ax.set_title(f"Textos {g}: DMO (proyectado) vs. visitantes (percibido)", pad=45)    ax.legend(frameon=False, ncol=2, fontsize=9, loc="lower center", bbox_to_anchor=(0.5, 1.0))    ax.spines[["top", "right"]].set_visible(False)    u.guardar(fig, ruta)def calcular(df, fuente, dmo, paleta, salida):    out = f"{salida}/temas"    os.makedirs(out, exist_ok=True)    df["texto_limpio"] = df["texto_limpio"].fillna("")    fuentes = u.orden(df, fuente, dmo)    filas = []    for g in ["positivos", "negativos"]:        df["tema_" + g], df["nombre_" + g] = -1, ""        idx = df.index[df["sentimiento"] == g[:-1]].values        if len(idx) < MINIMO:            print(f"  {g}: solo {len(idx)} textos, no se calculan temas")            continue        tf = TfidfVectorizer(ngram_range=(1, 2), min_df=5, max_df=0.5, max_features=5000,                             token_pattern=r"\b[a-zñ]{3,}\b", stop_words=QUITAR)        X = tf.fit_transform(df.loc[idx, "texto_limpio"])        voc = tf.get_feature_names_out()        B = (X > 0).astype(float).tocsc()        mods = {}        for k in RANGO:            m = NMF(n_components=k, init="nndsvda", random_state=1, max_iter=400)            mods[k] = (m.fit_transform(X), m.components_)        coh = {k: npmi(B, H) for k, (W, H) in mods.items()}        pd.Series(coh, name="npmi").to_csv(f"{out}/1_k_{g}.csv")        k = max(x for x in coh if coh[x] >= max(coh.values()) - TOL)        graf_k(coh, k, g, f"{out}/1_k_{g}.png")        W, H = mods[k]        tema = np.where(W.max(axis=1) > 0, W.argmax(axis=1), -1)        man = {t: n for (gg, t), n in NOMBRES.items() if gg == g}        nombres = {t: man[t] if len(man) == k else ", ".join(voc[np.argsort(-H[t])[:3]]) for t in range(k)}        df.loc[idx, "tema_" + g] = tema        df.loc[idx, "nombre_" + g] = [nombres.get(t, "") for t in tema]        d = df.loc[idx]        d = d[d["tema_" + g] >= 0]        for t in range(k):            nt = (d["tema_" + g] == t).sum()            if nt == 0:                continue            rep = df.loc[idx[np.argsort(-W[:, t])[:3]], "texto_base"].tolist()            filas.append({"grupo": g, "tema": t, "nombre": nombres[t], "textos": nt,                          "pct": round(nt / len(d) * 100, 1),                          "palabras_clave": ", ".join(voc[np.argsort(-H[t])[:10]]),                          **{f"comentario_{i + 1}": str(x)[:300] for i, x in enumerate(rep)},                          **{f"pct_{f}": round((d.loc[d[fuente] == f, "tema_" + g] == t).mean() * 100, 1)                             for f in fuentes if (d[fuente] == f).any()}})        r = pd.DataFrame([x for x in filas if x["grupo"] == g]).sort_values("textos")        n = d[fuente].value_counts()        graf_proyectado(r, g, [f for f in fuentes if n.get(f, 0) >= 30], n, paleta,                        f"{out}/2_proyectado_vs_percibido_{g}.png")    res = pd.DataFrame(filas)    res.to_csv(f"{out}/3_temas.csv", index=False)    return df, res